{
  "title": "Cusco close to home",
  "summary": "A gentle Sunday around the old town, with the market, the square and a couple of quiet stops all within a short stroll.",
  "stops": [
    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "We start where Cusco wakes up, among the fruit stalls and morning chatter.",
      "must_do_id": null
    },
    {
      "poi_id": "p1",
      "kind": "activity",
      "must_do_id": null,
      "note": "A slow turn around the square lets the early birds soak up the light before the crowds.",
      "must_do_id": null
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch sits right beside the square, so nobody has to wander far on a full stomach.",
      "must_do_id": null
    },
    {
      "poi_id": "p7",
      "kind": "activity",
      "must_do_id": null,
      "note": "A little chocolate stop keeps the afternoon sweet and the walking light.",
      "must_do_id": null
    },
    {
      "poi_id": "p18",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner is a short amble away, easy on the wallet and kind to tired feet.",
      "must_do_id": null
    }
  ]
}
